class Solution:
    def preimageSizeFZF(self, k: int) -> int:
        cnt, ans, x = 0, 0, 0
        while True:
            if cnt == k:
                ans += 1
            elif cnt > k:
                break
            x += 1
            t = x
            while t % 5 == 0:
                cnt += 1
                t //= 5
        return ans

