class Solution:
    def preimageSizeFZF(self, k: int) -> int:
        def z(x):
            c = 0
            while x:
                x //= 5
                c += x
            return c

        lo, hi = 0, 5 * (k + 1)
        while lo < hi:
            mid = (lo + hi) // 2
            if z(mid) < k:
                lo = mid + 1
            else:
                hi = mid
        return 5 if z(lo) == k else 0

