        return c;
    }
    int preimageSizeFZF(int k) {
        long long lo = 0, hi = 5LL * (k + 1);
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (z(mid) < k) lo = mid + 1;
            else hi = mid;
        }
