var preimageSizeFZF = function(k) {
    const z = x => {
        let c = 0;
        while (x > 0) { x = Math.floor(x / 5); c += x; }
        return c;
    };
    let lo = 0, hi = 5 * (k + 1);
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (z(mid) < k) lo = mid + 1;
        else hi = mid;
    }
    return z(lo) === k ? 5 : 0;
};
